insert into chunks (document_id, chunk_index, heading, content) values
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 120, 'B4.3.8', 'h) derivát vložený do pojistné smlouvy s touto hostitelskou smlouvou úzce souvisí, pokud vložený derivát a hostitelská pojistná smlouva jsou na sobě vzájemně natolik závislé, že účetní jednotka nemůže vložený derivát ocenit samostatně (tj. odděleně od hostitelské smlouvy). Nástroje obsahující vložené deriváty'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 121, 'B4.3.10', 'Přehodnocení vložených derivátů'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 122, 'B4.3.12', 'a) podnikové kombinace (jak ji definuje IFRS 3 Podnikové kombinace); b) podnikových kombinací mezi účetními jednotkami nebo podniky pod společnou kontrolou tak, jak je popisují odstavce B1–B4 IFRS 3; c) založení společného podniku, na který se vztahuje standard IFRS 11 Společná ujednání, nebo jejich možné přehodnocení k datu akvizice (53). Reklasifikace finančních aktiv (oddíl 4.4) Reklasifikace finančních aktiv'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 123, 'B4.4.1', 'a) účetní jednotka má portfolio komerčních půjček, které drží za účelem prodeje v krátkodobém horizontu. Účetní jednotka koupí společnost, která řídí komerční půjčky a její obchodní model spočívá v držení těchto půjček za účelem inkasa smluvních peněžních toků. Dané portfolio komerčních půjček již není na prodej a je nyní řízeno společně se získanými komerčními půjčkami, přičemž všechny jsou drženy za účelem inkasa smluvních peněžních toků; b) firma poskytující finanční služby se rozhodne ukončit svou činnost na retailovém hypotečním trhu. Tento podnik již nepřijímá nové zakázky a firma poskytující finanční služby aktivně nabízí své portfolio hypotečních úvěrů k prodeji.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 124, 'B4.4.3', 'a) změna záměru týkající se určitých finančních aktiv (i za předpokladu podstatných změn tržních podmínek); b) dočasný zánik určitého trhu finančních aktiv; c) převod finančních aktiv mezi jednotlivými částmi účetní jednotky s odlišnými obchodními modely.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 125, 'OCEŇOVÁNÍ (KAPITOLA 5)', 'Prvotní ocenění (oddíl 5.1)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 126, 'B5.1.2A', 'a) při oceňování požadovaném podle odstavce 5.1.1 v případě, že je reálná hodnota doložena kotovanou cenou pro stejné aktivum nebo závazek na aktivním trhu (tj. vstupem na úrovni 1) nebo založena na technice ocenění, která používá pouze údaje z pozorovatelných trhů. Účetní jednotka uzná rozdíl mezi reálnou hodnotou při prvotním uznání a transakční cenou jako zisk nebo ztrátu; b) ve všech ostatních případech při oceňování požadovaném podle odstavce 5.1.1 bude tento údaj upraven o odloženou výši rozdílu mezi reálnou hodnotou při prvotním uznání a transakční cenou. Po prvotním uznání účetní jednotka uzná tento odložený rozdíl jako zisk nebo ztrátu pouze tehdy, pokud vyplývá ze změny určitých faktorů (včetně času), které by účastníci trhu brali v úvahu při stanovení ceny aktiva nebo závazku. Následné oceňování (oddíly 5.2 a 5.3)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 127, 'B5.2.2A', 'Investice do kapitálových nástrojů a do smluv týkajících se těchto investic'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 128, 'B5.2.4', 'a) podstatná změna výkonnosti jednotky, do které se investovalo, v porovnání s rozpočty, plány nebo mezníky; b) změny očekávání z hlediska dosažení milníků technických výrobků jednotky, do které se investovalo; c) podstatná změna na trhu z hlediska vlastního kapitálu, výrobků nebo potenciálních výrobků jednotky, do které se investovalo; d) podstatná změna světového hospodářství nebo ekonomického prostředí, ve kterém jednotka, do které se investovalo, působí; e) podstatná změna výkonnosti srovnatelných účetních jednotek, nebo ocenění vyplývajících z celkového trhu; f) vnitřní záležitosti jednotky, do které se investovalo, jako například podvody, obchodní spory, soudní spory či změny řízení nebo strategie; g) důkazy z externích transakcí v rámci vlastního kapitálu jednotky, do které se investovalo, buď od jednotky, do které se investovalo (například nedávná emise vlastního kapitálu), nebo na základě převodů kapitálových nástrojů mezi třetími stranami.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 129, 'B5.2.6', 'Oceňování naběhlou hodnotou (oddíl 5.4) Metoda efektivní úrokové míry'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 130, 'B5.4.2', 'a) počáteční poplatky přijaté účetní jednotkou, které se týkají vzniku nebo akvizice finančního aktiva. Takové poplatky mohou zahrnovat kompenzaci za činnosti, jako je například posouzení finanční situace dlužníka, posouzení a vykazování záruk, kolaterálu a jiných bezpečnostních opatření, vyjednávání podmínek nástroje, přípravu a zpracování dokumentů a uzavření transakce. Tyto poplatky jsou nedílnou součástí vytváření angažovanosti ve vztahu k výslednému finančnímu nástroji; b) poplatky přijaté účetní jednotkou za úvěrový příslib v případě, že tento úvěrový příslib není oceněn v souladu s odst. 4.2.1 písm. a) a je pravděpodobné, že účetní jednotka uzavře konkrétní úvěrovou smlouvu. Tyto poplatky jsou považovány za kompenzaci stávající angažovanosti při akvizici finančního nástroje. Jestliže tento příslib vyprší, aniž by účetní jednotka poskytla daný úvěr, uzná se tento poplatek jako výnos při uplynutí platnosti; c) počáteční poplatky hrazené při vydání finančních závazků oceněných naběhlou hodnotou. Tyto poplatky jsou nedílnou součástí vytváření angažovanosti ve vztahu k výslednému finančnímu závazku. Účetní jednotka rozlišuje mezi poplatky a náklady, které jsou nedílnou součástí efektivní úrokové míry finančního závazku, a počátečními poplatky a transakčními náklady souvisejícími s právem poskytovat služby, jako jsou například služby správy investic.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 131, 'B5.4.3', 'a) poplatky účtované za správu úvěru; b) poplatky za úvěrové přísliby v případě, že úvěrový příslib není oceněn v souladu s odst. 4.2.1 písm. a) a není pravděpodobné, že bude uzavřeno určité úvěrové ujednání, a c) poplatky za syndikaci úvěru přijaté účetní jednotkou, která úvěr zprostředkuje, ale neponechá si pro sebe žádnou část úvěrového balíku (případně si ponechá část se stejnou efektivní úrokovou mírou a srovnatelným rizikem jako jiní účastníci).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 132, 'B5.4.7', 'Transakční náklady'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 133, 'B5.4.8', 'Odpis'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 134, 'B5.4.9', 'Znehodnocení (oddíl 5.5) Portfoliový a individuální základ pro posuzování'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 135, 'B5.5.5', 'a) typ nástroje; b) ratingy úvěrového rizika; c) typ kolaterálu; d) datum prvotního uznání; e) zbývající doba do splatnosti; f) průmyslové odvětví; g) zeměpisné umístění dlužníka a h) hodnota kolaterálu vztahujícího se k danému finančnímu aktivu, pokud má vliv na pravděpodobnost selhání (například úvěry bez postihu v některých jurisdikcích nebo poměry úvěru k hodnotě).'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 136, 'B5.5.6', 'Okamžik uznání očekávaných úvěrových ztrát za dobu trvání'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 137, 'B5.5.12', 'a) změnu rizika selhání od prvotního uznání; b) očekávanou dobu trvání finančního nástroje a c) přiměřené a doložitelné informace, které jsou dostupné bez vynaložení nepřiměřených nákladů nebo úsilí a které mohou ovlivnit úvěrové riziko.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 138, 'B5.5.14', 'a) daný finanční nástroj má podstatné platební závazky pouze v období přesahujícím následujících 12 měsíců; b) dojde ke změnám relevantních makroekonomických nebo jiných faktorů vztahujících se k úvěru, které nejsou dostatečně zohledněny v riziku selhání v následujících 12 měsících, nebo c) změny faktorů vztahujících se k úvěru mají dopad na úvěrové riziko finančního nástroje (nebo mají zřetelnější účinek) pouze v období přesahujícím následujících 12 měsíců. Určování, zda došlo k podstatnému zvýšení úvěrového rizika od prvotního uznání'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 139, 'B5.5.17', 'a) podstatné změny vnitřních cenových ukazatelů úvěrového rizika v důsledku změny úvěrového rizika od okamžiku zahájení včetně, ale nikoli výhradně, úvěrové marže, která by vznikla, pokud by určitý finanční nástroj nebo podobný finanční nástroj se stejnými podmínkami a stejnou protistranou nově vznikl nebo byl vydán k datu vykázání; b) jiné změny měr nebo podmínek stávajícího finančního nástroje, které by byly podstatně odlišné v případě, že by nástroj nově vznikl nebo byl vydán k datu vykázání (jako například přísnější dohody, zvýšené částky kolaterálu nebo záruk nebo vyšší ochrana příjmů) v důsledku změn úvěrového rizika finančního nástroje od prvotního uznání; c) podstatné změny externích tržních ukazatelů úvěrového rizika určitého finančního nástroje nebo podobných finančních nástrojů se stejnou očekávanou dobou trvání. Změny tržních ukazatelů úvěrového rizika zahrnují mimo jiné: i) úvěrovou marži; ii) ceny swapů úvěrového selhání pro dlužníka; iii) délku období nebo rozsah, v němž je reálná hodnota finančního aktiva nižší než jeho naběhlá hodnota, a iv) jiné tržní informace týkající se dlužníka, jako například změny cen dluhových a kapitálových nástrojů dlužníka; d) skutečná nebo očekávaná podstatná změna externího úvěrového ratingu daného finančního nástroje; e) skutečné nebo očekávané snížení interního úvěrového ratingu dlužníka nebo snížení behaviorálního scoringu užívaného při interním posuzování úvěrového rizika. Interní úvěrové ratingy a interní behaviorální scoring jsou spolehlivější, jsou-li vázány na externí ratingy nebo podporovány studiemi selhání;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 140, 'B5.5.17', 'f) stávající nebo očekávané nepříznivé změny finančních nebo ekonomických podmínek podniku, u nichž se očekává, že způsobí podstatnou změnu schopnosti dlužníka dostát svým dlužným závazkům, jako je například skutečné nebo očekávané zvýšení úrokových měr či skutečné nebo očekávané podstatné zvýšení míry nezaměstnanosti; g) skutečná nebo očekávaná podstatná změna provozních výsledků dlužníka. Jedná se například o skutečný nebo očekávaný pokles výnosů nebo marží, zvyšování provozních rizik, schodky pracovního kapitálu, snižující se kvalitu aktiv, zvýšený pákový efekt rozvahy, likviditu, problémy v oblasti vedení společnosti nebo změny rozsahu působnosti nebo organizační struktury podniku (například ukončení činnosti určitého segmentu podniku), jejichž výsledkem je podstatná změna schopnosti dlužníka dostát jeho dlužným závazkům; h) podstatná zvýšení úvěrového rizika jiných finančních nástrojů téhož dlužníka; i) skutečná nebo očekávaná podstatná nepříznivá změna regulatorního, ekonomického nebo technologického prostředí dlužníka, jejímž výsledkem je podstatná změna schopnosti dlužníka dostát jeho dlužným závazkům, jako je například pokles poptávky po produktu, který dlužník prodává v důsledku technologického posunu;'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 141, 'B5.5.17', 'j) podstatné změny hodnoty kolaterálu zajišťujícího daný závazek nebo kvality záruk třetích stran nebo úvěrových posílení, u nichž se předpokládá, že sníží ekonomickou motivaci dlužníka provádět plánované smluvní platby nebo budou mít jiný dopad na pravděpodobnost selhání. Jestliže například poklesne hodnota kolaterálu v důsledku poklesu cen domů, znamená to pro dlužníky v některých jurisdikcích větší motivaci k tomu, aby neplnili závazky ze svých hypoték; k) podstatná změna kvality záruky poskytnuté akcionářem (nebo mateřským podnikem jednotlivce), jestliže tento akcionář nebo mateřské podniky mají motivaci a finanční schopnost předejít neplnění závazků vložením kapitálu nebo peněžních prostředků; l) podstatné změny, jakými jsou například snížení finanční podpory mateřského podniku nebo jiného přidruženého podniku, či skutečná nebo očekávaná podstatná změna zvýšení kvality úvěrového aktiva, u nichž se očekává, že sníží ekonomickou motivaci dlužníka provádět plánované smluvní platby. Zvýšení nebo podpora kvality úvěrového aktiva zahrnuje zohlednění finanční situace ručitele a/nebo u podílů vydaných v rámci sekuritizace toho, zda se předpokládá, že podřízený podíl bude schopen absorbovat očekávané úvěrové ztráty (například z úvěrů, které slouží jako podklad daného cenného papíru);'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 142, 'B5.5.17', 'm) očekávané změny úvěrové dokumentace včetně očekávaného porušení smlouvy, které mohou vést ke vzdání se práv vyplývajících z ujednání nebo k jejich úpravě, k úrokovým prázdninám, ke zvýšení úrokové míry, které vyžaduje dodatečný kolaterál nebo záruky, případně k jiným změnám smluvního rámce daného nástroje; n) podstatné změny očekávané výkonnosti a chování dlužníka včetně změn v platební situaci dlužníků ve skupině (např. zvýšený očekávaný objem opožděných smluvních plateb nebo podstatné zvýšení očekávaného objemu dlužníků z kreditních karet, u kterých se předpokládá, že dosáhli svého úvěrového limitu nebo jej překročili nebo že splácejí minimální měsíční částku); o) změny přístupu účetní jednotky ke správě úvěrů ve vztahu k danému finančnímu nástroji; tj. na základě vznikajících ukazatelů změn úvěrového rizika finančního nástroje se předpokládá, že účetní jednotka použije aktivnější praktiky řízení úvěrového rizika, nebo že se zaměří na řízení daného nástroje včetně důkladnějšího dohledu nebo kontroly daného nástroje, případně provede konkrétní intervenci ve vztahu k dlužníkovi; p) informace o úvěrech po splatnosti včetně vyvratitelného předpokladu uvedeného v odstavci 5.5.11.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 143, 'B5.5.18', 'Vyvratitelný předpoklad více než 30 dnů po splatnosti'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 144, 'B5.5.21', 'Finanční nástroje,které mají k datu vykázání nízké úvěrové riziko'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 145, 'B5.5.24', 'Modifikace'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 146, 'B5.5.27', 'Vyčíslení očekávaných úvěrových ztrát Očekávané úvěrové ztráty'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 147, 'B5.5.29', 'a) smluvními peněžními toky splatnými účetní jednotce podle smlouvy a b) peněžními toky, jejichž inkaso účetní jednotka očekává.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 148, 'B5.5.30', 'a) smluvními peněžními toky, které jsou splatné účetní jednotce, jestliže držitel úvěrového příslibu čerpá úvěr, a b) peněžními toky, jejichž inkaso účetní jednotka očekává v případě čerpání úvěru.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 149, 'B5.5.35', 'Definice selhání'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 150, 'B5.5.37', 'Období, během kterého se odhadují očekávané úvěrové ztráty'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 151, 'B5.5.39', 'a) finanční nástroje nemají pevnou splatnost nebo strukturu splácení a obvykle mají ve smlouvě stanovenu krátkou lhůtu pro zrušení (například jeden den); b) smluvně stanovená možnost zrušení smlouvy není v běžném každodenním řízení finančního nástroje uplatňována a smlouvu lze zrušit jen tehdy, pokud účetní jednotka zjistí zvýšení úvěrového rizika na úrovni daného produktu, a c) finanční nástroje jsou řízeny na portfoliovém základě.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 152, 'B5.5.40', 'a) období, během kterého byla účetní jednotka vystavena úvěrovému riziku z podobných finančních nástrojů; b) za jak dlouho nastala související selhání u podobných finančních nástrojů po podstatném zvýšení úvěrového rizika a c) činnosti řízení úvěrového rizika, které účetní jednotka předpokládá provést po zvýšení úvěrového rizika z finančního nástroje, jako je například snížení nebo odstranění nevyčerpaných limitů. Pravděpodobnostně vážený výsledek'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 153, 'B5.5.43', 'Časová hodnota peněz'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 154, 'B5.5.48', 'Přiměřené a doložitelné informace'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 155, 'B5.5.54', 'Kolaterál'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 156, 'B5.5.55', 'Reklasifikace finančních aktiv (oddíl 5.6)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 157, 'B5.6.1', 'a) uznání úrokových výnosů se nezmění a účetní jednotka proto i nadále užívá stejnou efektivní úrokovou míru; b) vyčíslení očekávaných úvěrových ztrát se nezmění, protože obě kategorie oceňování uplatňují stejný přístup ke znehodnocení. Při reklasifikaci finančního aktiva z kategorie nástrojů oceňovaných reálnou hodnotou do ostatního úplného výsledku do kategorie nástrojů oceňovaných naběhlou hodnotou, by však opravná položka byla uznána jako úprava hrubé účetní hodnoty finančního aktiva ode dne reklasifikace. Při reklasifikaci finančního aktiva z kategorie nástrojů oceňovaných naběhlou hodnotou do kategorie nástrojů oceňovaných reálnou hodnotou do ostatního úplného výsledku, by opravná položka byla vyňata (a proto by již nebyla uznána jako úprava hrubé účetní hodnoty) a místo toho by byla uznána jako částka kumulovaného znehodnocení (nebo stejná částka) do ostatního úplného výsledku a byla by zveřejněna ode dne reklasifikace.'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 158, 'B5.6.2', 'Zisky a ztráty (oddíl 5.7)'),
('3ec40391-e0da-4687-bd26-9ad3a721bff7', 159, 'B5.7.4', 'Závazky označené jako nástroj oceňovaný reálnou hodnotou do hospodářského výsledku')
